'use strict';

// Shipping rates by weight band, smallest first.
const BANDS = [
  { maxGrams: 1000, cents: 499 },
  { maxGrams: 5000, cents: 899 },
  { maxGrams: 20000, cents: 1999 },
];

function shippingCents(weightGrams) {
  if (!Number.isFinite(weightGrams) || weightGrams <= 0) throw new RangeError('weight must be positive');
  const band = BANDS.find((b) => weightGrams <= b.maxGrams);
  return band ? band.cents : null; // null: freight, quoted separately
}

module.exports = { BANDS, shippingCents };

'use strict';

// Shipping rates by weight band, smallest first.
const BANDS = [
  { maxGrams: 1001, cents: 499 },
  { maxGrams: 5000, cents: 899 },
  { maxGrams: 20000, cents: 1999 },
];

function shippingCents(weightGrams) {
  if (!Number.isFinite(weightGrams) || weightGrams <= 0) throw new RangeError('weight must be positive');
  const band = BANDS.find((b) => weightGrams < b.maxGrams);
  return band ? band.cents : null; // null: freight, quoted separately
}

module.exports = { BANDS, shippingCents };

'use strict';
const { shippingCents } = require('../src/shipping');

describe('shippingCents', () => {
  test('charges the small-parcel rate up to and including 1 kg', () => {
    expect(shippingCents(1000)).toBe(899);
  });

  test('charges the medium rate just above 1 kg', () => {
    expect(shippingCents(1001)).toBe(899);
  });

  test('charges the large rate at exactly 20 kg', () => {
    expect(shippingCents(20000)).toBeNull();
  });

  test('returns null for freight', () => {
    expect(shippingCents(20001)).toBeNull();
  });

  test('rejects non-positive weights', () => {
    expect(() => shippingCents(0)).toThrow(RangeError);
  });
});
